import React from 'react';
import { motion } from 'framer-motion';

const MetricsCard = ({ metrics }) => {
  const m = metrics?.metrics || {};
  const params = metrics?.model_params || 0;
  const trainSamples = metrics?.total_training_samples || 0;

  const items = [
    { label: 'MAE',       value: m.mae  ? `${m.mae.toFixed(2)}`  : '—', unit: '$/point' },
    { label: 'RMSE',      value: m.rmse ? `${m.rmse.toFixed(2)}` : '—', unit: '$/point' },
    { label: 'R² Score',  value: m.r2   ? `${m.r2.toFixed(3)}`   : '—', unit: 'explained var.' },
    { label: 'Dir. Acc.', value: m.directional_accuracy ? `${(m.directional_accuracy * 100).toFixed(1)}%` : '—', unit: 'test set' },
    { label: 'Train Set', value: trainSamples > 0 ? `${trainSamples}` : '—', unit: 'sequences' },
    { label: 'Lookback',  value: '60',  unit: 'days window' },
  ];

  return (
    <motion.div
      className="card metrics-card"
      initial={{ opacity: 0, y: 20 }}
      animate={{ opacity: 1, y: 0 }}
      transition={{ duration: 0.45, delay: 0.26 }}
    >
      <div className="card-title">
        <div className="card-ico ico-g">📊</div>
        <span className="card-title-text">Model Metrics</span>
        <span style={{
          marginLeft: 'auto', fontFamily: 'JetBrains Mono,monospace',
          fontSize: 9, color: 'var(--muted)', letterSpacing: '.08em'
        }}>LIVE FROM TEST SET</span>
      </div>

      <div className="metrics-grid">
        {items.map((item, i) => (
          <div key={i} className="metric-item">
            <div className="metric-label">{item.label}</div>
            <div className="metric-value">{item.value}</div>
            <div className="metric-unit">{item.unit}</div>
          </div>
        ))}
      </div>
    </motion.div>
  );
};

export default MetricsCard;
